my_wish = input("Please state your wish:")

def grant_wish(wish):
    wish_components = wish.split()
    for component in wish_components:
        if "good" in component:
            return f"{wish} granted!"
        else:
            return "Wish rejected."

print(grant_wish(my_wish))

