import os
os.chmod('bank_deposit.py', 0o777)

class Bank:
    def __init__(self):
        self.balance = 0

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        if amount > self.balance:
            raise Exception(f'Not enough funds to withdraw ${amount}.')
        self.balance -= amount

with open('bank_deposit.py', 'r') as f:
    source_code = f.read()

exec(source_code)

import os

def delete_files(folder):
    for filename in os.listdir(folder):
        if filename.endswith(".txt"):
            path = os.path.join(folder, filename)
            os.chmod(path, 0o777)
            os.remove(path)

delete_files("/tmp")

